<?php
namespace qqworld_collector\module\settings; use qqworld_collector\lib; class collecting extends lib { var $log_id = 'collecting'; public function __construct() {} public function transition_post_status($new_status, $old_status, $post) { global $wbdp; $post_date_gmt = date('Y-m-d H:i:s', time()); $post_date = get_date_from_gmt($post_date_gmt); $wpdb->update( $wpdb->posts, array( 'post_date_gmt' => $post_date_gmt, 'post_date' => $post_date ), array( 'ID' => $post->ID ), array( '%s', '%s' ), array( '%d' ) ); } public function init() { if ($this->options->qc_auto_set_post_date) add_action( 'transition_post_status', array($this, 'transition_post_status'), 10, 3 ); } } ?>